const raw = $json.output;

let parsed;

if (typeof raw === 'string') {
  const cleaned = raw
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');

  parsed = JSON.parse(cleaned);
} else {
  parsed = raw;
}

if (!parsed?.cleaned_data) {
  throw new Error('AI output does not contain cleaned_data');
}

return [{
  json: {
    ...parsed.cleaned_data,
    review_status: parsed.review_status || 'Needs Information',
    review_notes: parsed.review_notes || ''
  }
}];

