const input = $('MEDIA CONTEXT').first().json;
const driveFolderId = $json.id || '';
const submissionId = input.submission_id;
const mediaItems = [];

function addMedia(files, type, folder) {
  // string হলে array বানাও
  if (typeof files === 'string' && files.trim() !== '') {
    files = [files];
  }
  if (!Array.isArray(files) || files.length === 0) return;

  for (const file of files) {
    const sourceUrl =
      typeof file === 'string'
        ? file.trim()
        : file.download_url || file.url || '';
    if (!sourceUrl) continue;

    const originalName =
      typeof file === 'object' && file.file_name
        ? file.file_name
        : sourceUrl.split('/').pop()?.split('?')[0] ||
          `${type}-${Date.now()}`;

    const safeName = originalName.replace(/[^a-zA-Z0-9._-]/g, '_');

    mediaItems.push({
      submission_id: submissionId,
      person_slug: input.person_slug,
      media_type: type,
      source_url: sourceUrl,
      file_name: safeName,
      mime_type:
        typeof file === 'object'
          ? file.mime_type || 'application/octet-stream'
          : 'application/octet-stream',
      size_bytes:
        typeof file === 'object'
          ? Number(file.size_bytes || 0)
          : 0,
      drive_folder_id: driveFolderId,
      storage_bucket: 'listing-media-public',
      storage_path:
        `${input.storage_base_path}/${folder}/` +
        `${Date.now()}-${mediaItems.length + 1}-${safeName}`
    });
  }
}

addMedia(input.photos, 'photo', 'photos');
addMedia(input.floor_plans, 'floor_plan', 'floor-plans');
addMedia(input.video_link, 'video', 'videos');

if (mediaItems.length === 0) {
  throw new Error('HAS MEDIA was true, but no downloadable media URL was found');
}

return mediaItems.map(media => ({ json: media }));

const input = $json;

const fullName = String(input.full_name || 'Unknown Submitter').trim();

const nameSlug = fullName
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '') || 'unknown';

const submissionId =
  input.submission_id ||
  `SUB-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

return [{
  json: {
    ...input,
    submission_id: submissionId,
    person_slug: nameSlug,
    drive_folder_name: `${fullName} - ${submissionId}`,
    storage_base_path: `${nameSlug}/${submissionId}`
  }
}];

