const gmailData = $('GMAIL TRIGGER').first();
const binary = gmailData.binary || {};
const json = gmailData.json;

const folderData = $('CRETE FOLDER1').first().json;

const senderName = json.from?.value?.[0]?.name || 'Unknown';
const senderEmail = json.from?.value?.[0]?.address || 'unknown';

const nameSlug = senderName
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '') || 'unknown';

for (const [key, file] of Object.entries(binary)) {
  const fileName = file.fileName || key;
  const mimeType = file.mimeType || 'application/octet-stream';
  const mediaType = mimeType.startsWith('image/') ? 'photo'
    : mimeType.startsWith('video/') ? 'video'
    : mimeType === 'application/pdf' ? 'floor_plan'
    : 'other';

  results.push({
    json: {
      submitter_email: senderEmail,
      person_slug: nameSlug,
      file_name: fileName,
      mime_type: mimeType,
      media_type: mediaType,
      storage_path: `${nameSlug}/attachments/${Date.now()}-${fileName}`,
      storage_bucket: 'listing-media-public',
      drive_folder_id: folderData.id,
    },
    binary: {
      data: file
    }
  });
}

return results;

