  .split(',')
  .map(id => id.trim())
  .filter(id => id.length > 0);

const allLeads = $('GET LEAD').all().map(i => i.json);

const newLeads = allLeads.filter(
  lead => !alreadyMatchedLeadIds.includes(lead['Lead ID'])
);

return [{
  json: {
    ...currentProperty,
    new_leads: newLeads,
    new_leads_count: newLeads.length,
    already_matched_lead_ids: alreadyMatchedLeadIds  // পরে agent-কে দিতে কাজে লাগবে
  }
}];

